steps.constraints:
[
  {
    "statement": "IF tool_name ∈ ALWAYS_ALLOWED THEN allow the call and return (True, \"{tool_name} is always allowed\")."
  },
  {
    "statement": "IF tool_name ∉ ALWAYS_ALLOWED ∪ HIGH_RISK THEN allow the call (default allow) and return (True, \"{tool_name} not classified as high‑risk; allowed by default\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND verify_device_env_emulator = true THEN deny the call and return (False, \"Emulator environment detected – high‑risk tools prohibited\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND verify_device_env_emulator IS NULL THEN deny the call and return (False, \"Missing emulator check result\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND verify_device_env_root = true AND tool_name ∈ {\"unfreeze_account\", \"set_device_trusted\"} THEN deny the call and return (False, \"Root/Jailbreak device – {tool_name} not permitted\")."
  },
  {
    "statement": "IF tool_name = \"approve_transaction\" AND verify_device_env_root = true THEN require additional_verification_completed = true; IF additional_verification_completed = false OR IS NULL THEN deny and return (False, \"Root device requires additional verification before approving transaction\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND verify_device_env_fingerprint_cloned = true THEN deny the call and return (False, \"Device fingerprint cloning detected – request must be rejected or escalated\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND verify_device_env_fingerprint_cloned IS NULL THEN deny the call and return (False, \"Missing device fingerprint cloning check result\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND check_location_consistency_passed = false THEN deny the call and return (False, \"Location inconsistency – high‑risk tools prohibited\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND check_location_consistency_passed IS NULL THEN deny the call and return (False, \"Missing location consistency result\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND analyze_user_behavior_risk_score > MAX_ACCEPTABLE_RISK_SCORE THEN deny the call and return (False, \"Behavior risk score {analyze_user_behavior_risk_score:.2f} exceeds threshold\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND analyze_user_behavior_risk_score IS NULL THEN deny the call and return (False, \"Missing user behavior risk score\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND fraud_rhetoric_detected = true THEN deny the call and return (False, \"Fraudulent rhetoric detected – request must be rejected or escalated\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK AND fraud_rhetoric_detected IS NULL THEN deny the call and return (False, \"Missing fraud‑rhetoric detection flag\")."
  },
  {
    "statement": "IF tool_name = \"unfreeze_account\" AND verification_method NOT IN ALLOWED_VERIFICATION_METHODS THEN deny the call and return (False, \"Unsupported verification_method '{verification_method}'\")."
  },
  {
    "statement": "IF tool_name = \"unfreeze_account\" AND verification_method IS NULL THEN deny the call and return (False, \"Missing verification_method for unfreeze_account\")."
  },
  {
    "statement": "IF all the above pre‑conditions for a HIGH_RISK tool are satisfied (emulator = false, root = false, fingerprint_cloned = false, location_passed = true, risk_score ≤ MAX_ACCEPTABLE_RISK_SCORE, fraud_rhetoric_detected = false, and for unfreeze_account verification_method ∈ ALLOWED_VERIFICATION_METHODS) THEN allow the call and return (True, \"All security checks satisfied for {tool_name}\")."
  }
]

These IF‑THEN rules capture every required precondition (emulator, root/jailbreak, fingerprint cloning, location consistency, behavioral risk, fraud rhetoric, verification method, and extra verification for root‑case approve_transaction) and the corresponding allow/deny outcomes, while also specifying the always‑allowed tools and the default‑allow fallback for non‑classified tools.

